73: void MockDmaManager::writeRegister(uint32_t offset, uint32_t value)
74: {
75:     uint32_t idx = offset / 4;
76:     if (idx < m_registers.size()) {
77:         m_registers[idx] = value;
78:     }
79: 
80:     // Interpret known registers
81:     switch (offset) {
82:     case 0x0000: // Center Frequency (stored in kHz)
83:         m_centerFreq = static_cast<double>(value) * 1e3;
84:         Logger::info(TAG, QString("Center Freq = %1 MHz").arg(m_centerFreq / 1e6, 0, 'f', 3));
