86:     case 0x0004: // Span (stored in kHz)
87:         m_span = static_cast<double>(value) * 1e3;
88:         Logger::info(TAG, QString("Span = %1 MHz").arg(m_span / 1e6, 0, 'f', 3));
89:         break;
90:     default:
91:         break;
92:     }
