129: void MockDmaManager::generateFrame()
130: {
131:     static thread_local std::mt19937 rng(42);
132:     std::normal_distribution<float> noiseDist(0.0f, 2.0f);
133: 
134:     const double startFreq = m_centerFreq - m_span / 2.0;
135:     const double freqStep  = m_span / m_fftSize;
136: 
137:     struct PreparedSignal {
138:         int centerBin;
139:         int halfWidthBins;
140:         float peakPower;
141:         double invTwoSigmaSq;
142:     };
143: 
144:     std::vector<PreparedSignal> prepSignals;
145:     prepSignals.reserve(m_signals.size());
146: 
147:     for (const auto& sig : m_signals) {
148:         double binPos = (sig.freqHz - startFreq) / freqStep;
149:         double sigmaBins = (sig.bwHz / 2.355) / freqStep;
150:         if (sigmaBins < 1.0) sigmaBins = 1.0;
151: 
152:         PreparedSignal ps;
153:         ps.centerBin = static_cast<int>(std::round(binPos));
154:         ps.halfWidthBins = static_cast<int>(std::ceil(4.0 * sigmaBins));
155:         ps.peakPower = std::pow(10.0f, static_cast<float>(sig.amplitudedBm) / 10.0f);
156:         ps.invTwoSigmaSq = 1.0 / (2.0 * sigmaBins * sigmaBins);
157:         prepSignals.push_back(ps);
158:     }
159: 
160:     const float baseNoisePower = std::pow(10.0f, static_cast<float>(m_noiseFloor) / 10.0f);
161: 
162:     for (int i = 0; i < m_fftSize; ++i) {
163:         float noiseFactor = std::pow(10.0f, noiseDist(rng) / 10.0f);
164:         float totalPower  = baseNoisePower * noiseFactor;
165: 
166:         for (const auto& ps : prepSignals) {
167:             int diffBins = i - ps.centerBin;
168:             if (std::abs(diffBins) <= ps.halfWidthBins) {
169:                 float sigPower = ps.peakPower * static_cast<float>(std::exp(-diffBins * diffBins * ps.invTwoSigmaSq));
170:                 totalPower += sigPower;
171:             }
172:         }
173: 
174:         m_frameBuffer[static_cast<size_t>(i)] = 10.0f * std::log10(totalPower);
175:     }
176: }
177: 
178: } // namespace rtsa
