30: void DmaRecvThread::run()
31: {
32:     Logger::info(TAG, "Thread started");
33:     m_running = true;
34: 
35: #ifdef Q_OS_WIN
36:     timeBeginPeriod(1); // Set Windows system timer resolution to 1ms
37: #endif
38: 
39:     m_hal->startAcquisition();
40: 
41:     while (m_running) {
42:         uint64_t frameId = 0;
43:         const float* rawData = m_hal->acquireFrame(frameId);
44: 
45:         if (!rawData) {
46:             if (m_running) {
47:                 Logger::warning(TAG, "acquireFrame returned null");
48:                 emit errorOccurred("DMA frame acquisition failed");
49:             }
50:             continue;
51:         }
52: 
53:         // Write into TripleBuffer
54:         SpectrumFrame& writeBuf = m_buffer->getWriteBuffer();
55:         int count = std::min(m_hal->fftSize(), SpectrumFrame::kMaxFftSize);
56:         std::memcpy(writeBuf.data.data(), rawData,
57:                     static_cast<size_t>(count) * sizeof(float));
58:         writeBuf.size    = count;
59:         writeBuf.frameId = frameId;
60: 
61:         m_buffer->publish();
62: 
63:         // Small microsecond yield so CPU doesn't burn 100% in loop
64:         QThread::usleep(500);
65:     }
66: 
