167: void DataProcessor::processFrame(const SpectrumFrame& raw)
168: {
169:     std::lock_guard<std::mutex> lock(m_mutex);
170: 
171:     // Detect dropped frames
172:     if (m_lastFrameId > 0 && raw.frameId > m_lastFrameId + 1) {
173:         uint64_t dropped = raw.frameId - m_lastFrameId - 1;
174:         m_dropCount += dropped;
175:     }
176:     m_lastFrameId = raw.frameId;
177: 
178:     int count = std::min(raw.size, m_fftSize);
179: 
180:     // Step 1: TracePipeline processing (Live / Primary trace)
181:     m_tracePipeline.process(raw.data.data(), count, m_processeddBm);
182: 
183:     // Additional Traces if enabled
184:     if (m_enableMaxHold) {
185:         m_maxHoldPipeline.process(raw.data.data(), count, m_maxHolddBm);
186:     }
187:     if (m_enableMinHold) {
188:         m_minHoldPipeline.process(raw.data.data(), count, m_minHolddBm);
189:     }
190:     if (m_enableAverage) {
191:         m_averagePipeline.process(raw.data.data(), count, m_averagedBm);
192:     }
193: 
194:     // Step 2: One-shot Marker triggers
195:     if (m_pendingPeakSearch) {
196:         m_markerEngine.searchPeak(m_searchMarkerId, m_processeddBm.data(), count, m_centerFreqHz, m_spanHz);
197:         m_pendingPeakSearch = false;
198:     }
199:     if (m_pendingNextPeak) {
200:         m_markerEngine.searchNextPeak(m_searchMarkerId, m_processeddBm.data(), count, m_centerFreqHz, m_spanHz);
201:         m_pendingNextPeak = false;
202:     }
203:     if (m_pendingNextPeakRight) {
204:         m_markerEngine.searchNextPeakRight(m_searchMarkerId, m_processeddBm.data(), count, m_centerFreqHz, m_spanHz);
205:         m_pendingNextPeakRight = false;
206:     }
207:     if (m_pendingNextPeakLeft) {
208:         m_markerEngine.searchNextPeakLeft(m_searchMarkerId, m_processeddBm.data(), count, m_centerFreqHz, m_spanHz);
209:         m_pendingNextPeakLeft = false;
210:     }
211:     if (m_pendingMinSearch) {
212:         m_markerEngine.searchMin(m_searchMarkerId, m_processeddBm.data(), count, m_centerFreqHz, m_spanHz);
213:         m_pendingMinSearch = false;
214:     }
