109: static void convertDbmToScreenPoints(const QVector<float>& dBmVec,
110:                                      const QRect& area,
111:                                      double refLevel,
112:                                      double totalRange,
113:                                      QVector<QPointF>& outPoints)
114: {
115:     const int count = dBmVec.size();
116:     if (count == 0 || area.width() <= 0 || area.height() <= 0) {
117:         outPoints.clear();
118:         return;
119:     }
120: 
121:     outPoints.clear();
122:     outPoints.reserve(count);
123: 
124:     auto mapY = [area, refLevel, totalRange](float val) -> double {
125:         double yNorm = (refLevel - static_cast<double>(val)) / totalRange;
126:         double y = area.top() + yNorm * area.height();
127:         return qBound(static_cast<double>(area.top()), y, static_cast<double>(area.bottom()));
128:     };
129: 
130:     // If decimated Min-Max buffer (pair per column)
131:     int numColumns = count / 2;
132:     if (count >= 2 && numColumns > 0) {
133:         const double xStep = static_cast<double>(area.width()) / std::max(1, numColumns - 1);
134: 
135:         for (int col = 0; col < numColumns; ++col) {
136:             double x = area.left() + col * xStep;
137:             float valMin = dBmVec[col * 2];
138:             float valMax = dBmVec[col * 2 + 1];
139: 
140:             double yTop    = mapY(valMax); // Higher dBm -> higher on screen (smaller Y)
141:             double yBottom = mapY(valMin); // Lower dBm  -> lower on screen (larger Y)
142: 
143:             outPoints.append(QPointF(x, yTop));
144:             outPoints.append(QPointF(x, yBottom));
145:         }
146:     } else {
147:         const double xStep = static_cast<double>(area.width()) / std::max(1, count - 1);
148:         for (int i = 0; i < count; ++i) {
149:             double x = area.left() + i * xStep;
150:             outPoints.append(QPointF(x, mapY(dBmVec[i])));
151:         }
152:     }
153: }
