414: void SpectrumPlot::drawMarkers(QPainter& painter)
415: {
416:     if (!m_markerEngine) return;
417: 
418:     const QRect area = plotArea();
419:     painter.setClipRect(area);
420:     painter.setRenderHint(QPainter::Antialiasing, true);
421: 
422:     const double totalRange = m_dbPerDiv * kGridDivY;
423:     const double startFreq = m_centerFreq - m_span / 2.0;
424: 
425:     std::map<int, int> xBucketCount;
426: 
427:     for (const auto& m : m_markerEngine->allMarkers()) {
428:         if (!m.active) continue;
429: 
430:         double xNorm = (m.freqHz - startFreq) / m_span;
431:         double yNorm = (m_refLevel - m.amplitude) / totalRange;
432: 
433:         double x = area.left() + xNorm * area.width();
434:         double y = area.top() + yNorm * area.height();
435: 
436:         if (x < area.left() || x > area.right() || y < area.top() || y > area.bottom()) continue;
437: 
438:         int xBucket = static_cast<int>(x / 24);
439:         int overlapIndex = xBucketCount[xBucket]++;
440:         double yOffset = overlapIndex * 20.0;
441: 
442:         // Inverted triangle marker
443:         QPolygonF triangle;
444:         triangle << QPointF(x, y - yOffset)
445:                  << QPointF(x - 5, y - 8 - yOffset)
446:                  << QPointF(x + 5, y - 8 - yOffset);
447: 
448:         painter.setBrush(m.color);
449:         painter.setPen(QPen(Qt::black, 1));
450:         painter.drawPolygon(triangle);
451: 
452:         // Marker Tag Bubble
453:         QString tagText = QString("M%1: %2 %3dBm")
454:                               .arg(m.id)
455:                               .arg(formatFrequency(m.freqHz))
456:                               .arg(m.amplitude, 0, 'f', 1);
457:         if (m.isDelta) {
458:             tagText = QString("ΔM%1: %2 %3dB")
459:                           .arg(m.id)
460:                           .arg(formatFrequency(m.deltaFreqHz))
461:                           .arg(m.deltaAmplitude, 0, 'f', 1);
462:         }
463: 
464:         QFont tagFont("KaiTi", 8, QFont::Bold);
465:         painter.setFont(tagFont);
466:         QFontMetrics fm(tagFont);
467:         int tagW = fm.horizontalAdvance(tagText) + 8;
468:         int tagH = 15;
469: 
470:         int tagX = static_cast<int>(x) - tagW / 2;
471:         int tagY = static_cast<int>(y - 24 - yOffset);
472:         tagX = qBound(area.left() + 2, tagX, area.right() - tagW - 2);
473: 
474:         // Tag Background
475:         painter.fillRect(QRect(tagX, tagY, tagW, tagH), QColor(0x0e, 0x11, 0x1a, 230));
476:         painter.setPen(QPen(m.color, 1));
477:         painter.drawRect(QRect(tagX, tagY, tagW, tagH));
478: 
479:         // Tag Text
