#ifndef RTSA_TRIPLE_BUFFER_H
#define RTSA_TRIPLE_BUFFER_H

#include <array>
#include <atomic>
#include <cstdint>

namespace rtsa {

/// Lock-free triple buffer for single-producer single-consumer scenarios.
///
/// Writer thread calls getWriteBuffer() -> writes data -> publish().
/// Reader thread calls consume() -> if true, getReadBuffer() has new data.
///
/// When writer is faster than reader, intermediate frames are automatically
/// skipped (the reader always gets the latest published frame).
///
/// Thread safety: exactly ONE writer thread and ONE reader thread.
template<typename T>
class TripleBuffer {
public:
    TripleBuffer()
        : m_writeIdx(0)
        , m_readIdx(1)
        , m_pendingState(2) // Initial pending index 2, HAS_NEW_DATA bit (0x4) not set
    {
    }

    /// [Writer thread] Get reference to the write buffer.
    /// The writer can freely modify this buffer without affecting the reader.
    T& getWriteBuffer()
    {
        return m_buffers[m_writeIdx];
    }

    /// [Writer thread] Publish the written data.
    /// Atomically swaps the write buffer with the pending buffer and sets new data flag.
    void publish()
    {
        uint32_t newState = static_cast<uint32_t>(m_writeIdx) | kHasNewDataFlag;
        uint32_t oldState = m_pendingState.exchange(newState, std::memory_order_acq_rel);
        m_writeIdx = static_cast<int>(oldState & kIndexMask);
    }

    /// [Reader thread] Try to consume the latest published data.
    /// Atomically swaps the pending buffer with the read buffer and clears new data flag.
    /// @return true if new data was available and is now in getReadBuffer().
    bool consume()
    {
        uint32_t current = m_pendingState.load(std::memory_order_acquire);
        while (current & kHasNewDataFlag) {
            uint32_t desired = static_cast<uint32_t>(m_readIdx) & kIndexMask;
            if (m_pendingState.compare_exchange_weak(current, desired,
                                                    std::memory_order_acq_rel,
                                                    std::memory_order_acquire)) {
                m_readIdx = static_cast<int>(current & kIndexMask);
                return true;
            }
        }
        return false;
    }

    /// [Reader thread] Get const reference to the read buffer.
    /// Valid after consume() returns true.
    const T& getReadBuffer() const
    {
        return m_buffers[m_readIdx];
    }

private:
    static constexpr uint32_t kIndexMask      = 0x03;
    static constexpr uint32_t kHasNewDataFlag = 0x04;

    std::array<T, 3> m_buffers;

    int m_writeIdx;                              // Only touched by writer thread
    int m_readIdx;                               // Only touched by reader thread
    std::atomic<uint32_t> m_pendingState;        // Shared: lower 2 bits = pending index, bit 2 = has_new_data
};

} // namespace rtsa

#endif // RTSA_TRIPLE_BUFFER_H

