#ifndef RTSA_MOCK_DMA_MANAGER_H
#define RTSA_MOCK_DMA_MANAGER_H

#include "IHalInterface.h"

#include <QObject>
#include <atomic>
#include <cstdint>
#include <mutex>
#include <vector>

namespace rtsa {

/// Mock implementation of IHalInterface for desktop development.
/// Generates simulated spectrum data (noise floor + configurable signal peaks)
/// without requiring real FPGA hardware.
class MockDmaManager : public QObject, public IHalInterface {
    Q_OBJECT

public:
    struct SignalParams {
        double freqHz;        // Signal center frequency (Hz)
        double amplitudedBm;  // Peak amplitude (dBm)
        double bwHz;          // Signal bandwidth at -3dB (Hz)
    };

    explicit MockDmaManager(int fftSize = 4096, QObject* parent = nullptr);
    ~MockDmaManager() override;

    // ── IHalInterface ──
    bool startAcquisition() override;
    void stopAcquisition() override;
    const float* acquireFrame(uint64_t& frameId) override;
    void writeRegister(uint32_t offset, uint32_t value) override;
    uint32_t readRegister(uint32_t offset) override;
    int fftSize() const override;
    bool isAcquiring() const override;

    // ── Mock configuration ──
    void setFrameIntervalMs(int ms);
    void setNoiseFloor(double dBm);
    void setSignals(const std::vector<SignalParams>& newSignals);

private:
    void generateFrame();

    int m_fftSize;
    std::atomic<int> m_frameIntervalMs{1};

    mutable std::mutex m_configMutex;
    double m_noiseFloor;

    // Simulated instrument parameters (set via writeRegister)
    double m_centerFreq; // Hz
    double m_span;       // Hz

    // Mock signal definitions
    std::vector<SignalParams> m_signals;

    // Frame output buffer
    std::vector<float> m_frameBuffer;
    std::atomic<uint64_t> m_frameId{0};
    std::atomic<bool> m_acquiring{false};

    // Register shadow (simulated FPGA register space)
    std::vector<uint32_t> m_registers;
};

} // namespace rtsa

#endif // RTSA_MOCK_DMA_MANAGER_H

