#include "MockDmaManager.h"
#include "Logger.h"

#include <QThread>
#include <algorithm>
#include <cmath>
#include <random>

namespace rtsa {

static const char* TAG = "MockDMA";

MockDmaManager::MockDmaManager(int fftSize, QObject* parent)
    : QObject(parent)
    , m_fftSize(std::max(1, fftSize))
    , m_frameIntervalMs(1) // 1000 fps default
    , m_noiseFloor(-100.0)
    , m_centerFreq(2.4e9)
    , m_span(100e6)
    , m_frameBuffer(static_cast<size_t>(std::max(1, fftSize)), 0.0f)
    , m_registers(256, 0)
{
    // Default signals: three WiFi channels
    m_signals = {
        {2.380e9, -55.0, 2e6},  // Channel A (inside span)
        {2.412e9, -30.0, 2e6},  // Channel 1 (highest peak)
        {2.437e9, -45.0, 2e6},  // Channel 6 (second peak)
    };

    Logger::info(TAG,
                 QString("Created: fftSize=%1, centerFreq=%2 MHz, span=%3 MHz")
                     .arg(m_fftSize)
                     .arg(m_centerFreq / 1e6, 0, 'f', 1)
                     .arg(m_span / 1e6, 0, 'f', 1));
}

MockDmaManager::~MockDmaManager()
{
    stopAcquisition();
}

bool MockDmaManager::startAcquisition()
{
    m_acquiring = true;
    m_frameId   = 0;
    Logger::info(TAG, "Acquisition started");
    return true;
}

void MockDmaManager::stopAcquisition()
{
    if (m_acquiring.exchange(false)) {
        Logger::info(TAG, "Acquisition stopped");
    }
}

const float* MockDmaManager::acquireFrame(uint64_t& frameId)
{
    if (!m_acquiring) {
        return nullptr;
    }

    // Simulate DMA frame interval
    int interval = m_frameIntervalMs.load(std::memory_order_relaxed);
    if (interval > 0) {
        QThread::msleep(interval);
    }

    if (!m_acquiring) {
        return nullptr;
    }

    generateFrame();
    frameId = m_frameId.fetch_add(1, std::memory_order_relaxed);

    return m_frameBuffer.data();
}

void MockDmaManager::writeRegister(uint32_t offset, uint32_t value)
{
    std::lock_guard<std::mutex> lock(m_configMutex);
    uint32_t idx = offset / 4;
    if (idx < m_registers.size()) {
        m_registers[idx] = value;
    }

    // Interpret known registers
    switch (offset) {
    case 0x0000: // Center Frequency (stored in kHz)
        m_centerFreq = static_cast<double>(value) * 1e3;
        Logger::info(TAG, QString("Center Freq = %1 MHz").arg(m_centerFreq / 1e6, 0, 'f', 3));
        break;
    case 0x0004: // Span (stored in kHz)
        m_span = static_cast<double>(value) * 1e3;
        Logger::info(TAG, QString("Span = %1 MHz").arg(m_span / 1e6, 0, 'f', 3));
        break;
    default:
