    }
}

uint32_t MockDmaManager::readRegister(uint32_t offset)
{
    std::lock_guard<std::mutex> lock(m_configMutex);
    uint32_t idx = offset / 4;
    if (idx < m_registers.size()) {
        return m_registers[idx];
    }
    return 0;
}

int MockDmaManager::fftSize() const
{
    return m_fftSize;
}

bool MockDmaManager::isAcquiring() const
{
    return m_acquiring.load(std::memory_order_relaxed);
}

void MockDmaManager::setFrameIntervalMs(int ms)
{
    m_frameIntervalMs.store(std::max(1, ms), std::memory_order_relaxed);
}

void MockDmaManager::setNoiseFloor(double dBm)
{
    std::lock_guard<std::mutex> lock(m_configMutex);
    m_noiseFloor = dBm;
}

void MockDmaManager::setSignals(const std::vector<SignalParams>& newSignals)
{
    std::lock_guard<std::mutex> lock(m_configMutex);
    m_signals = newSignals;
}

void MockDmaManager::generateFrame()
{
    // Snapshot config under lock to prevent data race
    double centerFreq = 2.4e9;
    double span = 100e6;
    double noiseFloor = -100.0;
    std::vector<SignalParams> signalsSnapshot;

    {
        std::lock_guard<std::mutex> lock(m_configMutex);
        centerFreq = m_centerFreq;
        span = m_span;
        noiseFloor = m_noiseFloor;
        signalsSnapshot = m_signals;
    }

    static thread_local std::mt19937 rng(42);
    std::normal_distribution<float> noiseDist(0.0f, 2.0f);

    const double startFreq = centerFreq - span / 2.0;
    const double freqStep  = (span > 0.0 && m_fftSize > 0) ? (span / m_fftSize) : 1.0;

    struct PreparedSignal {
        int centerBin;
        int halfWidthBins;
        float peakPower;
        double invTwoSigmaSq;
    };

    std::vector<PreparedSignal> prepSignals;
    prepSignals.reserve(signalsSnapshot.size());

    for (const auto& sig : signalsSnapshot) {
        double binPos = (sig.freqHz - startFreq) / freqStep;
        double sigmaBins = (sig.bwHz / 2.355) / freqStep;
        if (sigmaBins < 1.0) sigmaBins = 1.0;

        PreparedSignal ps;
        ps.centerBin = static_cast<int>(std::round(binPos));
        ps.halfWidthBins = static_cast<int>(std::ceil(4.0 * sigmaBins));
        ps.peakPower = std::pow(10.0f, static_cast<float>(sig.amplitudedBm) / 10.0f);
        ps.invTwoSigmaSq = 1.0 / (2.0 * sigmaBins * sigmaBins);
        prepSignals.push_back(ps);
    }

    const float baseNoisePower = std::pow(10.0f, static_cast<float>(noiseFloor) / 10.0f);

    for (int i = 0; i < m_fftSize; ++i) {
        float noiseFactor = std::pow(10.0f, noiseDist(rng) / 10.0f);
        float totalPower  = baseNoisePower * noiseFactor;

        for (const auto& ps : prepSignals) {
            int diffBins = i - ps.centerBin;
            if (std::abs(diffBins) <= ps.halfWidthBins) {
                float sigPower = ps.peakPower * static_cast<float>(std::exp(-diffBins * diffBins * ps.invTwoSigmaSq));
                totalPower += sigPower;
            }
        }

        m_frameBuffer[static_cast<size_t>(i)] = 10.0f * std::log10(std::max(1e-20f, totalPower));
    }
}

