#include "DmaRecvThread.h"
#include "Logger.h"

#include <algorithm>
#include <cstring>

#ifdef Q_OS_WIN
#include <windows.h>
#include <timeapi.h>
#endif

namespace rtsa {

static const char* TAG = "T1-DMA";

DmaRecvThread::DmaRecvThread(IHalInterface* hal,
                             TripleBuffer<SpectrumFrame>* buffer,
                             QObject* parent)
    : QThread(parent)
    , m_hal(hal)
    , m_buffer(buffer)
{
}

void DmaRecvThread::stopThread()
{
    m_running = false;
    if (m_hal) {
        m_hal->stopAcquisition();
    }
}

void DmaRecvThread::run()
{
    Logger::info(TAG, "Thread started");
    m_running = true;

#ifdef Q_OS_WIN
    timeBeginPeriod(1); // Set Windows system timer resolution to 1ms
#endif

    if (!m_hal || !m_hal->startAcquisition()) {
        Logger::error(TAG, "Failed to start HAL acquisition");
        emit errorOccurred("DMA acquisition initialization failed");
#ifdef Q_OS_WIN
        timeEndPeriod(1);
#endif
        return;
    }

    while (m_running) {
        uint64_t frameId = 0;
        const float* rawData = m_hal->acquireFrame(frameId);

        if (!rawData) {
            if (m_running) {
                Logger::warning(TAG, "acquireFrame returned null, backing off");
                emit errorOccurred("DMA frame acquisition failed");
                QThread::msleep(10); // Backoff to avoid spinning CPU and log flooding
            }
            continue;
        }

        // Write into TripleBuffer
        SpectrumFrame& writeBuf = m_buffer->getWriteBuffer();
        int count = std::min(m_hal->fftSize(), SpectrumFrame::kMaxFftSize);
        std::memcpy(writeBuf.data.data(), rawData,
                    static_cast<size_t>(count) * sizeof(float));
        writeBuf.size    = count;
        writeBuf.frameId = frameId;

        m_buffer->publish();

        // Small microsecond yield so CPU doesn't burn 100% in loop
        QThread::usleep(500);
    }

    if (m_hal) {
        m_hal->stopAcquisition();
    }

#ifdef Q_OS_WIN
    timeEndPeriod(1); // Restore Windows timer resolution
#endif

    Logger::info(TAG, "Thread stopped");
}

} // namespace rtsa

