#include "MarkerEngine.h"
#include <algorithm>
#include <cmath>

namespace rtsa {

static const QColor kMarkerColors[6] = {
    QColor(0xff, 0xdd, 0x00), // M1: Bright Yellow
    QColor(0x00, 0xe5, 0xff), // M2: Cyan
    QColor(0xff, 0x00, 0x7f), // M3: Magenta / Pink
    QColor(0xff, 0x91, 0x00), // M4: Orange
    QColor(0x76, 0xff, 0x03), // M5: Lime Green
    QColor(0xd5, 0x00, 0xf9)  // M6: Purple
};

MarkerEngine::MarkerEngine()
{
    for (int i = 0; i < kMaxMarkers; ++i) {
        m_markers[i].id = i + 1;
        m_markers[i].active = false;
        m_markers[i].color = kMarkerColors[i];
    }
}

MarkerInfo& MarkerEngine::marker(int id)
{
    int idx = std::clamp(id - 1, 0, kMaxMarkers - 1);
    return m_markers[idx];
}

const MarkerInfo& MarkerEngine::marker(int id) const
{
    int idx = std::clamp(id - 1, 0, kMaxMarkers - 1);
    return m_markers[idx];
}

void MarkerEngine::setMarkerActive(int id, bool active)
{
    if (id >= 1 && id <= kMaxMarkers) {
        m_markers[id - 1].active = active;
    }
}

void MarkerEngine::setMarkerBin(int id, int binIndex, double centerFreqHz, double spanHz, int fftSize)
{
    if (fftSize <= 0 || id < 1 || id > kMaxMarkers) return;

    auto& m = marker(id);
    m.binIndex = std::clamp(binIndex, 0, fftSize - 1);
    double startFreq = centerFreqHz - spanHz / 2.0;
    m.freqHz = startFreq + (static_cast<double>(m.binIndex) / fftSize) * spanHz;
}

void MarkerEngine::setGlobalDelta(bool enable, int refMarkerId)
{
    m_globalDeltaEnabled = enable;
    m_globalRefMarkerId  = std::clamp(refMarkerId, 1, kMaxMarkers);

    if (enable) {
        marker(m_globalRefMarkerId).active = true;
    }
}

void MarkerEngine::setContinuousPeak(int id, bool enable)
{
    if (id >= 1 && id <= kMaxMarkers) {
        m_markers[id - 1].continuousPeak = enable;
        if (enable) {
            m_markers[id - 1].active = true;
        }
    }
}

bool MarkerEngine::isContinuousPeak(int id) const
{
    if (id >= 1 && id <= kMaxMarkers) {
        return m_markers[id - 1].continuousPeak;
    }
    return false;
}

void MarkerEngine::findLocalPeaks(const float* dBmArray, int size, double centerFreqHz, double spanHz)
{
    m_detectedPeaks.clear();
    if (!dBmArray || size < 3) return;

    double startFreq = centerFreqHz - spanHz / 2.0;
    const int windowRadius = std::max(5, size / 200);
    const float noiseFloorThreshold = -110.0f;

    for (int i = windowRadius; i < size - windowRadius; ++i) {
        if (dBmArray[i] < noiseFloorThreshold) continue;

        bool isLocalMax = true;
        float minNeighbor = dBmArray[i];

        for (int j = i - windowRadius; j <= i + windowRadius; ++j) {
            if (j != i) {
                if (dBmArray[j] > dBmArray[i]) {
                    isLocalMax = false;
                    break;
                }
                minNeighbor = std::min(minNeighbor, dBmArray[j]);
            }
        }

        // Peak excursion requirement: peak must be at least m_excursiondB above neighboring minimum
        if (isLocalMax && (dBmArray[i] - minNeighbor >= m_excursiondB)) {
            LocalPeak peak;
            peak.binIndex  = i;
            peak.amplitude = dBmArray[i];
            peak.freqHz    = startFreq + (static_cast<double>(i) / size) * spanHz;
            m_detectedPeaks.push_back(peak);
        }
    }

    std::sort(m_detectedPeaks.begin(), m_detectedPeaks.end(), [](const LocalPeak& a, const LocalPeak& b) {
        return a.amplitude > b.amplitude;
    });
}

// Ultra-fast O(N) single-pass peak search
void MarkerEngine::searchPeak(int id, const float* dBmArray, int size, double centerFreqHz, double spanHz)
{
    if (!dBmArray || size <= 0 || id < 1 || id > kMaxMarkers) return;

    int maxBin = 0;
    float maxVal = dBmArray[0];

    for (int i = 1; i < size; ++i) {
        if (dBmArray[i] > maxVal) {
            maxVal = dBmArray[i];
            maxBin = i;
        }
    }

    auto& m = marker(id);
    m.active = true;
    m.binIndex = maxBin;
    m.amplitude = maxVal;
    double startFreq = centerFreqHz - spanHz / 2.0;
    m.freqHz = startFreq + (static_cast<double>(maxBin) / size) * spanHz;
}

void MarkerEngine::searchNextPeak(int id, const float* dBmArray, int size, double centerFreqHz, double spanHz)
{
    if (id < 1 || id > kMaxMarkers) return;
    findLocalPeaks(dBmArray, size, centerFreqHz, spanHz);

    if (m_detectedPeaks.empty()) {
        // If no local peak passes excursion, fallback to global peak
        searchPeak(id, dBmArray, size, centerFreqHz, spanHz);
        return;
    }

    auto& m = marker(id);
    m.active = true;

    int currentPeakRank = -1;
    for (size_t i = 0; i < m_detectedPeaks.size(); ++i) {
        if (std::abs(m_detectedPeaks[i].binIndex - m.binIndex) <= 15) {
            currentPeakRank = static_cast<int>(i);
            break;
        }
    }

    int nextRank = (currentPeakRank + 1) % m_detectedPeaks.size();

    m.binIndex  = m_detectedPeaks[nextRank].binIndex;
    m.amplitude = m_detectedPeaks[nextRank].amplitude;
    m.freqHz    = m_detectedPeaks[nextRank].freqHz;
}

void MarkerEngine::searchNextPeakRight(int id, const float* dBmArray, int size, double centerFreqHz, double spanHz)
{
    if (id < 1 || id > kMaxMarkers) return;
    findLocalPeaks(dBmArray, size, centerFreqHz, spanHz);

    auto& m = marker(id);
    const LocalPeak* bestRight = nullptr;
    double minRightDiff = 1e12;

    for (const auto& p : m_detectedPeaks) {
        if (p.freqHz > m.freqHz + (spanHz / size)) {
            double diff = p.freqHz - m.freqHz;
            if (diff < minRightDiff) {
                minRightDiff = diff;
                bestRight = &p;
            }
        }
    }

    if (bestRight) {
        m.active = true;
        m.binIndex  = bestRight->binIndex;
        m.amplitude = bestRight->amplitude;
        m.freqHz    = bestRight->freqHz;
    }
}

void MarkerEngine::searchNextPeakLeft(int id, const float* dBmArray, int size, double centerFreqHz, double spanHz)
{
    if (id < 1 || id > kMaxMarkers) return;
    findLocalPeaks(dBmArray, size, centerFreqHz, spanHz);

    auto& m = marker(id);
    const LocalPeak* bestLeft = nullptr;
    double minLeftDiff = 1e12;

    for (const auto& p : m_detectedPeaks) {
        if (p.freqHz < m.freqHz - (spanHz / size)) {
            double diff = m.freqHz - p.freqHz;
            if (diff < minLeftDiff) {
                minLeftDiff = diff;
                bestLeft = &p;
            }
        }
    }

    if (bestLeft) {
        m.active = true;
        m.binIndex  = bestLeft->binIndex;
        m.amplitude = bestLeft->amplitude;
        m.freqHz    = bestLeft->freqHz;
    }
}

void MarkerEngine::searchMin(int id, const float* dBmArray, int size, double centerFreqHz, double spanHz)
{
    if (!dBmArray || size <= 0 || id < 1 || id > kMaxMarkers) return;

    int minBin = 0;
    float minVal = dBmArray[0];

    for (int i = 1; i < size; ++i) {
        if (dBmArray[i] < minVal) {
            minVal = dBmArray[i];
            minBin = i;
        }
    }

    auto& m = marker(id);
    m.active = true;
    m.binIndex = minBin;
    m.amplitude = minVal;
    double startFreq = centerFreqHz - spanHz / 2.0;
    m.freqHz = startFreq + (static_cast<double>(minBin) / size) * spanHz;
}

void MarkerEngine::updateMarkers(const float* dBmArray, int size, double centerFreqHz, double spanHz)
{
    if (!dBmArray || size <= 0) return;

    double startFreq = centerFreqHz - spanHz / 2.0;

    // Update frequencies & amplitudes for all active markers
    for (auto& m : m_markers) {
        if (!m.active) continue;

        if (m.binIndex >= 0 && m.binIndex < size) {
            m.amplitude = dBmArray[m.binIndex];
            m.freqHz = startFreq + (static_cast<double>(m.binIndex) / size) * spanHz;
        }
    }

    // Compute global Delta for all active markers relative to globalRefMarkerId
    if (m_globalDeltaEnabled && m_globalRefMarkerId >= 1 && m_globalRefMarkerId <= kMaxMarkers) {
        const auto& refM = m_markers[m_globalRefMarkerId - 1];

        for (auto& m : m_markers) {
            if (!m.active) continue;

            if (m.id == m_globalRefMarkerId) {
                m.isDelta = false;
            } else {
                m.isDelta = true;
                m.refMarkerId = m_globalRefMarkerId;
                if (refM.active) {
                    m.deltaFreqHz = m.freqHz - refM.freqHz;
                    m.deltaAmplitude = m.amplitude - refM.amplitude;
                }
            }
        }
    } else {
        for (auto& m : m_markers) {
            m.isDelta = false;
        }
    }
}

} // namespace rtsa

