#ifndef RTSA_TRACE_DECIMATOR_H
#define RTSA_TRACE_DECIMATOR_H

#include <vector>

namespace rtsa {

/// Min-Max Pixel Decimator and equal-interval decimator.
/// Compresses an N-point FFT trace into 2 * outColumns points
/// by finding the minimum and maximum dBm value within each pixel column bucket.
/// Preserves narrow spectral peaks and deep notches reliably.
class TraceDecimator {
public:
    /// Outputs interleaved min/max pairs (2 * outColumns elements).
    static void decimateMinMax(const float* inputdBm,
                               int inputCount,
                               int targetPixels,
                               std::vector<float>& outputdBm);

    /// Outputs single peak/mean value per bucket for spectrogram / waterfall.
    static void decimateEqualInterval(const float* inputdBm,
                                      int inputCount,
                                      int targetBins,
                                      std::vector<float>& outputdBm);
};

} // namespace rtsa

#endif // RTSA_TRACE_DECIMATOR_H

