#include "TraceDecimator.h"
#include <algorithm>
#include <cmath>

namespace rtsa {

void TraceDecimator::decimateMinMax(const float* inputdBm,
                                    int inputCount,
                                    int targetPixels,
                                    std::vector<float>& outputdBm)
{
    if (!inputdBm || inputCount <= 0 || targetPixels <= 0) {
        outputdBm.clear();
        return;
    }

    // If input is smaller than target pixels, output each point as min=val, max=val pair
    if (inputCount <= targetPixels) {
        outputdBm.resize(static_cast<size_t>(inputCount * 2));
        for (int i = 0; i < inputCount; ++i) {
            outputdBm[static_cast<size_t>(i * 2)]     = inputdBm[i];
            outputdBm[static_cast<size_t>(i * 2 + 1)] = inputdBm[i];
        }
        return;
    }

    outputdBm.resize(static_cast<size_t>(targetPixels * 2));

    double pointsPerPixel = static_cast<double>(inputCount) / targetPixels;

    for (int px = 0; px < targetPixels; ++px) {
        int startIdx = static_cast<int>(std::floor(px * pointsPerPixel));
        int endIdx   = static_cast<int>(std::floor((px + 1) * pointsPerPixel));

        startIdx = std::clamp(startIdx, 0, inputCount - 1);
        endIdx   = std::clamp(endIdx, startIdx + 1, inputCount);

        float minVal = inputdBm[startIdx];
        float maxVal = inputdBm[startIdx];

        for (int i = startIdx + 1; i < endIdx; ++i) {
            minVal = std::min(minVal, inputdBm[i]);
            maxVal = std::max(maxVal, inputdBm[i]);
        }

        // Pair min and max for each pixel column
        outputdBm[static_cast<size_t>(px * 2)]     = minVal;
        outputdBm[static_cast<size_t>(px * 2 + 1)] = maxVal;
    }
}

void TraceDecimator::decimateEqualInterval(const float* inputdBm,
                                           int inputCount,
                                           int targetBins,
                                           std::vector<float>& outputdBm)
{
    if (!inputdBm || inputCount <= 0 || targetBins <= 0) {
        outputdBm.clear();
        return;
    }

    if (inputCount <= targetBins) {
        outputdBm.assign(inputdBm, inputdBm + inputCount);
        return;
    }

    outputdBm.resize(static_cast<size_t>(targetBins));
    double pointsPerBin = static_cast<double>(inputCount) / targetBins;

    for (int b = 0; b < targetBins; ++b) {
        int startIdx = static_cast<int>(std::floor(b * pointsPerBin));
        int endIdx   = static_cast<int>(std::floor((b + 1) * pointsPerBin));

        startIdx = std::clamp(startIdx, 0, inputCount - 1);
        endIdx   = std::clamp(endIdx, startIdx + 1, inputCount);

        float maxVal = inputdBm[startIdx];
        for (int i = startIdx + 1; i < endIdx; ++i) {
            maxVal = std::max(maxVal, inputdBm[i]);
        }
        outputdBm[static_cast<size_t>(b)] = maxVal;
    }
}

} // namespace rtsa

