#ifndef RTSA_DATA_PROCESSOR_H
#define RTSA_DATA_PROCESSOR_H

#include "ProcessedFrame.h"
#include "SpectrumFrame.h"
#include "TripleBuffer.h"
#include "TracePipeline.h"
#include "MarkerEngine.h"

#include <QThread>
#include <atomic>
#include <mutex>
#include <vector>

namespace rtsa {

enum class MarkerCmdType {
    PeakSearch,
    NextPeak,
    NextPeakRight,
    NextPeakLeft,
    MinSearch,
    PeakToCenter
};

struct MarkerCommand {
    MarkerCmdType type;
    int markerId;
};

class DataProcessor : public QThread {
    Q_OBJECT

public:
    DataProcessor(TripleBuffer<SpectrumFrame>* buffer,
                  int fftSize,
                  QObject* parent = nullptr);

    void stopThread();

    void setTraceMode(TraceMode mode);
    void setTraceEnabled(int traceIndex, bool enabled);
    bool isTraceEnabled(int traceIndex) const;
    void resetTrace();
    void resetAllTraces();

    void setParams(double centerFreqHz, double spanHz);

    // Thread-safe Marker operations
    void setMarkerActive(int markerId, bool active);
    void setMarkerBin(int markerId, int binIndex);
    void setGlobalDelta(bool enable, int refMarkerId = 1);
    void clearAllMarkers();
    void setContinuousPeak(int markerId, bool enabled);

    void triggerPeakSearch(int markerId = 1);
    void triggerNextPeak(int markerId = 1);
    void triggerNextPeakRight(int markerId = 1);
    void triggerNextPeakLeft(int markerId = 1);
    void triggerMinSearch(int markerId = 1);
    void triggerPeakToCenter();

    std::vector<float> currentSpectrumTrace() const;

    uint64_t processedFrameCount() const { return m_processedCount.load(std::memory_order_relaxed); }
    uint64_t droppedFrameCount() const { return m_dropCount.load(std::memory_order_relaxed); }

signals:
    void frameReady(const rtsa::ProcessedFrame& frame);
    void markersUpdated();
    void peakToCenterCalculated(double peakFreqHz);

protected:
    void run() override;

private:
    void processFrame(const SpectrumFrame& raw);

    TripleBuffer<SpectrumFrame>* m_buffer;
    int m_fftSize;
    std::atomic<bool> m_running{false};

    TracePipeline m_tracePipeline;   // Trace 1 (Live or selected mode)
    TracePipeline m_maxHoldPipeline; // Trace 2 (Max Hold)
    TracePipeline m_minHoldPipeline; // Trace 3 (Min Hold)
    TracePipeline m_averagePipeline; // Trace 4 (Average)

    bool m_enableLive = true;
    bool m_enableMaxHold = false;
    bool m_enableMinHold = false;
    bool m_enableAverage = false;

    MarkerEngine m_markerEngine;

    double m_centerFreqHz = 2.4e9;
    double m_spanHz       = 100e6;

    mutable std::mutex m_mutex;
    std::vector<float> m_processeddBm;
    std::vector<float> m_maxHolddBm;
    std::vector<float> m_minHolddBm;
    std::vector<float> m_averagedBm;

    // Instance-level decimated work buffers
    std::vector<float> m_decimateddBm;
    std::vector<float> m_waterfalldBm;
    std::vector<float> m_decimatedMaxHold;
    std::vector<float> m_decimatedMinHold;
    std::vector<float> m_decimatedAverage;

    std::atomic<uint64_t> m_processedCount{0};
    std::atomic<uint64_t> m_dropCount{0};
    uint64_t m_lastFrameId = 0;
    bool m_hasLastFrame    = false;

    std::vector<MarkerCommand> m_markerCommands;
};

} // namespace rtsa

#endif // RTSA_DATA_PROCESSOR_H

