    m_markerCommands.push_back({MarkerCmdType::PeakToCenter, 1});
}

void DataProcessor::run()
{
    Logger::info(TAG, QString("Thread started (fftSize=%1, interval=16ms)").arg(m_fftSize));
    m_running = true;

    QTimer timer;
    timer.setTimerType(Qt::PreciseTimer);
    connect(&timer, &QTimer::timeout, [this]() {
        if (!m_running) return;

        if (m_buffer->consume()) {
            const SpectrumFrame& frame = m_buffer->getReadBuffer();
            processFrame(frame);
        }
    });
    timer.start(16);

    exec();

    Logger::info(TAG, QString("Thread stopped. Processed: %1, Dropped: %2")
                          .arg(m_processedCount.load())
                          .arg(m_dropCount.load()));
}

void DataProcessor::processFrame(const SpectrumFrame& raw)
{
    double peakCenterFreq = -1.0;
    ProcessedFrame result;

    {
        std::lock_guard<std::mutex> lock(m_mutex);

        // Detect dropped frames accurately (handles starting frame 0)
        if (m_hasLastFrame && raw.frameId > m_lastFrameId + 1) {
            uint64_t dropped = raw.frameId - m_lastFrameId - 1;
            m_dropCount.fetch_add(dropped, std::memory_order_relaxed);
        }
        m_lastFrameId  = raw.frameId;
        m_hasLastFrame = true;

        int count = std::min(raw.size, m_fftSize);
        if (count <= 0) return;

        // Step 1: TracePipeline processing (Live / Primary trace)
        m_tracePipeline.process(raw.data.data(), count, m_processeddBm);

        // Additional Traces if enabled
        if (m_enableMaxHold) {
            m_maxHoldPipeline.process(raw.data.data(), count, m_maxHolddBm);
        }
        if (m_enableMinHold) {
            m_minHoldPipeline.process(raw.data.data(), count, m_minHolddBm);
        }
        if (m_enableAverage) {
            m_averagePipeline.process(raw.data.data(), count, m_averagedBm);
        }

        // Step 2: Process queued Marker commands
        for (const auto& cmd : m_markerCommands) {
            switch (cmd.type) {
            case MarkerCmdType::PeakSearch:
                m_markerEngine.searchPeak(cmd.markerId, m_processeddBm.data(), count, m_centerFreqHz, m_spanHz);
                break;
            case MarkerCmdType::NextPeak:
                m_markerEngine.searchNextPeak(cmd.markerId, m_processeddBm.data(), count, m_centerFreqHz, m_spanHz);
                break;
            case MarkerCmdType::NextPeakRight:
                m_markerEngine.searchNextPeakRight(cmd.markerId, m_processeddBm.data(), count, m_centerFreqHz, m_spanHz);
                break;
            case MarkerCmdType::NextPeakLeft:
                m_markerEngine.searchNextPeakLeft(cmd.markerId, m_processeddBm.data(), count, m_centerFreqHz, m_spanHz);
                break;
            case MarkerCmdType::MinSearch:
                m_markerEngine.searchMin(cmd.markerId, m_processeddBm.data(), count, m_centerFreqHz, m_spanHz);
                break;
            case MarkerCmdType::PeakToCenter:
                m_markerEngine.searchPeak(1, m_processeddBm.data(), count, m_centerFreqHz, m_spanHz);
                if (m_markerEngine.marker(1).active) {
                    peakCenterFreq = m_markerEngine.marker(1).freqHz;
                }
                break;
            }
        }
        m_markerCommands.clear();

        // Continuous Peak
        for (const auto& m : m_markerEngine.allMarkers()) {
            if (m.continuousPeak && m.active) {
                m_markerEngine.searchPeak(m.id, m_processeddBm.data(), count, m_centerFreqHz, m_spanHz);
            }
        }

        // Step 3: Update existing markers (frequencies, levels, and delta calculations)
        m_markerEngine.updateMarkers(m_processeddBm.data(), count, m_centerFreqHz, m_spanHz);

        // Step 4: Min-Max Pixel Decimation (Compress points -> 800 pixel buckets * 2 = 1600 points)
        const int targetPixels = 800;
        TraceDecimator::decimateMinMax(m_processeddBm.data(), count, targetPixels, m_decimateddBm);
        TraceDecimator::decimateEqualInterval(m_processeddBm.data(), count, targetPixels, m_waterfalldBm);

        // Step 5: Prepare ProcessedFrame
        result.frameId      = raw.frameId;
        result.dropCount    = m_dropCount.load(std::memory_order_relaxed);
        result.showLive     = m_enableLive;
        result.showMaxHold  = m_enableMaxHold;
        result.showMinHold  = m_enableMinHold;
        result.showAverage  = m_enableAverage;
        result.centerFreqHz = m_centerFreqHz;
        result.spanHz       = m_spanHz;

        // Snapshot Marker state
        result.markerSnapshot.markers = m_markerEngine.allMarkers();
        result.markerSnapshot.globalDeltaEnabled = m_markerEngine.isGlobalDeltaEnabled();
        result.markerSnapshot.globalRefMarkerId = m_markerEngine.globalRefMarkerId();

#if QT_VERSION >= QT_VERSION_CHECK(6, 0, 0)
        result.dBm.assign(m_decimateddBm.begin(), m_decimateddBm.end());
        result.waterfalldBm.assign(m_waterfalldBm.begin(), m_waterfalldBm.end());
#else
        result.dBm = QVector<float>::fromStdVector(m_decimateddBm);
        result.waterfalldBm = QVector<float>::fromStdVector(m_waterfalldBm);
#endif

        if (m_enableMaxHold && !m_maxHolddBm.empty()) {
            TraceDecimator::decimateMinMax(m_maxHolddBm.data(), count, targetPixels, m_decimatedMaxHold);
#if QT_VERSION >= QT_VERSION_CHECK(6, 0, 0)
            result.traceMaxHold.assign(m_decimatedMaxHold.begin(), m_decimatedMaxHold.end());
#else
            result.traceMaxHold = QVector<float>::fromStdVector(m_decimatedMaxHold);
#endif
        }

        if (m_enableMinHold && !m_minHolddBm.empty()) {
            TraceDecimator::decimateMinMax(m_minHolddBm.data(), count, targetPixels, m_decimatedMinHold);
#if QT_VERSION >= QT_VERSION_CHECK(6, 0, 0)
            result.traceMinHold.assign(m_decimatedMinHold.begin(), m_decimatedMinHold.end());
#else
            result.traceMinHold = QVector<float>::fromStdVector(m_decimatedMinHold);
#endif
        }

        if (m_enableAverage && !m_averagedBm.empty()) {
            TraceDecimator::decimateMinMax(m_averagedBm.data(), count, targetPixels, m_decimatedAverage);
#if QT_VERSION >= QT_VERSION_CHECK(6, 0, 0)
            result.traceAverage.assign(m_decimatedAverage.begin(), m_decimatedAverage.end());
#else
            result.traceAverage = QVector<float>::fromStdVector(m_decimatedAverage);
#endif
        }

        m_processedCount.fetch_add(1, std::memory_order_relaxed);
    }

    if (peakCenterFreq > 0.0) {
        emit peakToCenterCalculated(peakCenterFreq);
    }

    emit frameReady(result);
    emit markersUpdated();
}

} // namespace rtsa

