void DataProcessor::processFrame(const SpectrumFrame& raw)
{
    std::lock_guard<std::mutex> lock(m_mutex);

    // Detect dropped frames
    if (m_lastFrameId > 0 && raw.frameId > m_lastFrameId + 1) {
        uint64_t dropped = raw.frameId - m_lastFrameId - 1;
        m_dropCount += dropped;
