    // Additional Traces if enabled
    if (m_enableMaxHold) {
        m_maxHoldPipeline.process(raw.data.data(), count, m_maxHolddBm);
    }
    if (m_enableMinHold) {
        m_minHoldPipeline.process(raw.data.data(), count, m_minHolddBm);
    }
    if (m_enableAverage) {
        m_averagePipeline.process(raw.data.data(), count, m_averagedBm);
