        m_pendingNextPeak = false;
    }
    if (m_pendingNextPeakRight) {
        m_markerEngine.searchNextPeakRight(m_searchMarkerId, m_processeddBm.data(), count, m_centerFreqHz, m_spanHz);
        m_pendingNextPeakRight = false;
    }
    if (m_pendingNextPeakLeft) {
        m_markerEngine.searchNextPeakLeft(m_searchMarkerId, m_processeddBm.data(), count, m_centerFreqHz, m_spanHz);
        m_pendingNextPeakLeft = false;
    }
    if (m_pendingMinSearch) {
        m_markerEngine.searchMin(m_searchMarkerId, m_processeddBm.data(), count, m_centerFreqHz, m_spanHz);
        m_pendingMinSearch = false;
