#ifndef RTSA_PARAM_TRANSACTION_H
#define RTSA_PARAM_TRANSACTION_H

#include "IHalInterface.h"
#include <QString>

namespace rtsa {

enum class ParamId {
    CenterFreq, // Hz
    Span,       // Hz
    RefLevel,   // dBm
    DbPerDiv    // dB
};

class ParamTransaction {
public:
    explicit ParamTransaction(IHalInterface* hal);

    void setCenterFreq(double hz);
    void setSpan(double hz);
    void setRefLevel(double dBm);
    void setDbPerDiv(double db);

    bool validate(QString& errorReason);
    bool commit();
    void rollback();

    double pendingCenterFreq() const { return m_pendingCenterFreq; }
    double pendingSpan() const { return m_pendingSpan; }
    double pendingRefLevel() const { return m_pendingRefLevel; }
    double pendingDbPerDiv() const { return m_pendingDbPerDiv; }

    double committedCenterFreq() const { return m_committedCenterFreq; }
    double committedSpan() const { return m_committedSpan; }
    double committedRefLevel() const { return m_committedRefLevel; }
    double committedDbPerDiv() const { return m_committedDbPerDiv; }

private:
    IHalInterface* m_hal;

    double m_pendingCenterFreq = 2.4e9;
    double m_pendingSpan       = 100e6;
    double m_pendingRefLevel   = 0.0;
    double m_pendingDbPerDiv   = 10.0;

    double m_committedCenterFreq = 2.4e9;
    double m_committedSpan       = 100e6;
    double m_committedRefLevel   = 0.0;
    double m_committedDbPerDiv   = 10.0;

    bool m_dirtyCenterFreq = false;
    bool m_dirtySpan       = false;
    bool m_dirtyRefLevel   = false;
    bool m_dirtyDbPerDiv   = false;
};

} // namespace rtsa

#endif // RTSA_PARAM_TRANSACTION_H

