#include "ParamTransaction.h"
#include "Logger.h"
#include <algorithm>
#include <cmath>

namespace rtsa {

static const char* TAG = "ParamTxn";

ParamTransaction::ParamTransaction(IHalInterface* hal)
    : m_hal(hal)
{
}

void ParamTransaction::setCenterFreq(double hz)
{
    m_pendingCenterFreq = hz;
    m_dirtyCenterFreq = true;
}

void ParamTransaction::setSpan(double hz)
{
    m_pendingSpan = hz;
    m_dirtySpan = true;
}

void ParamTransaction::setRefLevel(double dBm)
{
    m_pendingRefLevel = dBm;
    m_dirtyRefLevel = true;
}

void ParamTransaction::setDbPerDiv(double db)
{
    m_pendingDbPerDiv = db;
    m_dirtyDbPerDiv = true;
}

bool ParamTransaction::validate(QString& errorReason)
{
    // Finite numeric checks
    if (!std::isfinite(m_pendingCenterFreq) || !std::isfinite(m_pendingSpan) ||
        !std::isfinite(m_pendingRefLevel) || !std::isfinite(m_pendingDbPerDiv)) {
        errorReason = "Parameters must be finite numbers";
        return false;
    }

    // Bounds check for 10 MHz ~ 6 GHz RF range
    if (m_pendingCenterFreq < 10e6 || m_pendingCenterFreq > 6.0e9) {
        errorReason = "Center Frequency must be between 10 MHz and 6 GHz";
        return false;
    }

    if (m_pendingSpan < 1e3 || m_pendingSpan > 6.0e9) {
        errorReason = "Span must be between 1 kHz and 6.0 GHz";
        return false;
    }

    // Combination check: Center ± Span/2 must stay strictly within 10 MHz to 6.0 GHz
    double startFreq = m_pendingCenterFreq - m_pendingSpan / 2.0;
    double stopFreq  = m_pendingCenterFreq + m_pendingSpan / 2.0;

    if (startFreq < 10e6 - 1e-3 || stopFreq > 6.0e9 + 1e-3) {
        errorReason = QString("Frequency range [%1 MHz, %2 MHz] exceeds instrument hardware limit [10 MHz, 6000 MHz]")
                          .arg(startFreq / 1e6, 0, 'f', 3)
                          .arg(stopFreq / 1e6, 0, 'f', 3);
        return false;
    }

    if (m_pendingRefLevel < -120.0 || m_pendingRefLevel > 30.0) {
        errorReason = "Ref Level must be between -120 dBm and +30 dBm";
        return false;
    }

    if (m_pendingDbPerDiv < 1.0 || m_pendingDbPerDiv > 20.0) {
        errorReason = "dB/div must be between 1 dB and 20 dB";
        return false;
    }

    return true;
}

bool ParamTransaction::commit()
{
    QString error;
    if (!validate(error)) {
        Logger::error(TAG, "Validation failed: " + error);
        return false;
    }

    if (!m_hal) {
        Logger::error(TAG, "HAL interface is null");
        return false;
    }

    if (m_dirtyCenterFreq) {
        m_hal->writeRegister(0x00, static_cast<uint32_t>(m_pendingCenterFreq / 1e3));
        m_committedCenterFreq = m_pendingCenterFreq;
    }
    if (m_dirtySpan) {
        m_hal->writeRegister(0x04, static_cast<uint32_t>(m_pendingSpan / 1e3));
        m_committedSpan = m_pendingSpan;
    }
    if (m_dirtyRefLevel) {
        m_hal->writeRegister(0x08, static_cast<uint32_t>(m_pendingRefLevel * 100));
        m_committedRefLevel = m_pendingRefLevel;
    }
    if (m_dirtyDbPerDiv) {
        m_hal->writeRegister(0x0C, static_cast<uint32_t>(m_pendingDbPerDiv * 100));
        m_committedDbPerDiv = m_pendingDbPerDiv;
    }

    m_dirtyCenterFreq = false;
    m_dirtySpan       = false;
    m_dirtyRefLevel   = false;
    m_dirtyDbPerDiv   = false;

    Logger::info(TAG, "Transaction committed successfully");
    return true;
}

void ParamTransaction::rollback()
{
    m_pendingCenterFreq = m_committedCenterFreq;
    m_pendingSpan       = m_committedSpan;
    m_pendingRefLevel   = m_committedRefLevel;
    m_pendingDbPerDiv   = m_committedDbPerDiv;

    m_dirtyCenterFreq = false;
    m_dirtySpan       = false;
    m_dirtyRefLevel   = false;
    m_dirtyDbPerDiv   = false;
    Logger::info(TAG, "Transaction rolled back to committed snapshot");
}

} // namespace rtsa

