void MarkerCard::updateMarkers(const std::array<MarkerInfo, 6>& markers)
{
    int activeCount = 0;

    for (int i = 0; i < 6; ++i) {
        const auto& m = markers[i];
        auto& row = m_rows[i];

        if (m.active) {
            activeCount++;
            row.container->show();

            row.lblId->setText(QString("M%1").arg(m.id));
            row.lblFreq->setText(formatFrequency(m.freqHz));
            row.lblAmp->setText(QString("%1 dBm").arg(m.amplitude, 0, 'f', 1));

            auto setLabelColor = [&](QLabel* lbl, const QColor& col) {
                QPalette pal = lbl->palette();
                pal.setColor(QPalette::WindowText, col);
                lbl->setPalette(pal);
            };

            setLabelColor(row.lblId, m.color);
            setLabelColor(row.lblFreq, m.color);
            setLabelColor(row.lblAmp, m.color);
            setLabelColor(row.lblDelta, m.color);

            if (m.isDelta) {
                int refId = (m.refMarkerId >= 1) ? m.refMarkerId : 1;
                row.lblDelta->setText(QString("Δ(M%1-M%2): %3, %4 dB")
                                          .arg(m.id)
                                          .arg(refId)
                                          .arg(formatFrequency(m.deltaFreqHz))
                                          .arg(m.deltaAmplitude, 0, 'f', 1));
            } else {
                row.lblDelta->setText("--");
            }
        } else {
            row.container->hide();
        }
    }

    adjustSize();

    if (activeCount > 0) {
        if (isHidden()) {
            show();
            if (!m_userMoved) {
                resetToDefaultPosition();
            }
        }
    } else {
        hide();
    }
}

