#ifndef RTSA_SPECTRUM_PLOT_H
#define RTSA_SPECTRUM_PLOT_H

#include "MarkerCard.h"
#include "MarkerEngine.h"
#include "ProcessedFrame.h"

#include <QElapsedTimer>
#include <QPixmap>
#include <QVector>
#include <QWidget>
#include <QPoint>
#include <QMenu>

namespace rtsa {

class SpectrumPlot : public QWidget {
    Q_OBJECT

public:
    explicit SpectrumPlot(QWidget* parent = nullptr);

    // ── Instrument parameters ──
    void setCenterFreq(double hz);
    void setSpan(double hz);
    void setRefLevel(double dBm);
    void setDbPerDiv(double db);

    double centerFreq() const { return m_centerFreq; }
    double span() const { return m_span; }
    double refLevel() const { return m_refLevel; }
    double dbPerDiv() const { return m_dbPerDiv; }

    void setTraceLiveColor(const QColor& color);
    QColor traceLiveColor() const { return m_colorTraceLive; }

    // ── Performance stats ──
    double lastPaintTimeMs() const { return m_lastPaintTimeMs; }
    double currentFps() const { return m_currentFps; }

public slots:
    void onNewFrame(const rtsa::ProcessedFrame& frame);

signals:
    void parameterChanged();
    void centerFreqUserChanged(double hz);
    void spanUserChanged(double hz);
    void refLevelUserChanged(double dBm);
    void peakSearchRequested(int markerId);
    void peakToCenterRequested();
    void resetTracesRequested();
    void fullSpanRequested();
    void screenshotRequested();

protected:
    void paintEvent(QPaintEvent* event) override;
    void resizeEvent(QResizeEvent* event) override;
    void wheelEvent(QWheelEvent* event) override;
    void mousePressEvent(QMouseEvent* event) override;
    void mouseMoveEvent(QMouseEvent* event) override;
    void mouseReleaseEvent(QMouseEvent* event) override;
    void contextMenuEvent(QContextMenuEvent* event) override;

private:
    void rebuildGridCache();
    void recomputeScreenPoints();
    void drawInfoBar(QPainter& painter);
    void drawCurves(QPainter& painter);
    void drawMarkers(QPainter& painter);
    void updateFpsCounter();

    QRect plotArea() const;
    QString formatFrequency(double hz) const;

    // ── Instrument state ──
    double m_centerFreq = 2.4e9;
    double m_span       = 100e6;
    double m_refLevel   = 0.0;
    double m_dbPerDiv   = 10.0;

    // ── Mouse Drag & Zoom State ──
    bool m_isPlotDragging        = false;
    QPoint m_dragStartPos;
    double m_dragStartCenterFreq = 2.4e9;
    double m_dragStartRefLevel   = 0.0;
    QPoint m_lastMousePos;

    // ── Layout margins (pixels) ──
    static constexpr int kMarginLeft   = 70;
    static constexpr int kMarginRight  = 30;
    static constexpr int kMarginTop    = 30;
    static constexpr int kMarginBottom = 42;
    static constexpr int kGridDivX     = 10;
    static constexpr int kGridDivY     = 10;

    // ── Rendering ──
    QPixmap m_gridCache;
    bool m_gridDirty = true;

    // Multi-trace coordinate buffers
    QVector<QPointF> m_pointsLive;
    QVector<QPointF> m_pointsMaxHold;
    QVector<QPointF> m_pointsMinHold;
    QVector<QPointF> m_pointsAverage;
    bool m_showLive     = true;
    bool m_showMaxHold  = false;
    bool m_showMinHold  = false;
    bool m_showAverage  = false;
    QColor m_colorTraceLive = QColor(0x00, 0xe5, 0xff);

    ProcessedFrame m_lastFrame;
    bool m_hasFrame = false;

    uint64_t m_frameId   = 0;
    uint64_t m_dropCount = 0;

    // ── FPS counter ──
    double m_lastPaintTimeMs = 0.0;
    double m_currentFps      = 0.0;
    int m_fpsFrameCount      = 0;
    QElapsedTimer m_fpsTimer;

    MarkerSnapshot m_markerSnapshot;
    MarkerCard* m_markerCard = nullptr;
};

} // namespace rtsa

#endif // RTSA_SPECTRUM_PLOT_H

