// ── Real-time data reception from T2 ──

static void convertDbmToScreenPoints(const QVector<float>& dBmVec,
                                     const QRect& area,
                                     double refLevel,
                                     double totalRange,
                                     QVector<QPointF>& outPoints)
{
    const int count = dBmVec.size();
    if (count == 0 || area.width() <= 0 || area.height() <= 0) {
        outPoints.clear();
        return;
    }

    outPoints.clear();
    outPoints.reserve(count);

    auto mapY = [area, refLevel, totalRange](float val) -> double {
        double yNorm = (refLevel - static_cast<double>(val)) / totalRange;
        double y = area.top() + yNorm * area.height();
        return qBound(static_cast<double>(area.top()), y, static_cast<double>(area.bottom()));
    };

    // If decimated Min-Max buffer (pair per column)
    int numColumns = count / 2;
    if (count >= 2 && numColumns > 0) {
        const double xStep = static_cast<double>(area.width()) / std::max(1, numColumns - 1);

        for (int col = 0; col < numColumns; ++col) {
            double x = area.left() + col * xStep;
            float valMin = dBmVec[col * 2];
            float valMax = dBmVec[col * 2 + 1];

            double yTop    = mapY(valMax); // Higher dBm -> higher on screen (smaller Y)
            double yBottom = mapY(valMin); // Lower dBm  -> lower on screen (larger Y)

            outPoints.append(QPointF(x, yTop));
            outPoints.append(QPointF(x, yBottom));
        }
    } else {
        const double xStep = static_cast<double>(area.width()) / std::max(1, count - 1);
        for (int i = 0; i < count; ++i) {
            double x = area.left() + i * xStep;
            outPoints.append(QPointF(x, mapY(dBmVec[i])));
        }
    }
}

void SpectrumPlot::recomputeScreenPoints()
{
    if (!m_hasFrame) return;

    const QRect area = plotArea();
    if (area.width() <= 0 || area.height() <= 0) return;

    const double totalRange = m_dbPerDiv * kGridDivY;

    m_showLive    = m_lastFrame.showLive;
    m_showMaxHold = m_lastFrame.showMaxHold;
    m_showMinHold = m_lastFrame.showMinHold;
    m_showAverage = m_lastFrame.showAverage;

    if (m_showLive) {
        convertDbmToScreenPoints(m_lastFrame.dBm, area, m_refLevel, totalRange, m_pointsLive);
    }
    if (m_showMaxHold) {
        convertDbmToScreenPoints(m_lastFrame.traceMaxHold, area, m_refLevel, totalRange, m_pointsMaxHold);
    }
    if (m_showMinHold) {
        convertDbmToScreenPoints(m_lastFrame.traceMinHold, area, m_refLevel, totalRange, m_pointsMinHold);
    }
    if (m_showAverage) {
        convertDbmToScreenPoints(m_lastFrame.traceAverage, area, m_refLevel, totalRange, m_pointsAverage);
    }
}

void SpectrumPlot::onNewFrame(const rtsa::ProcessedFrame& frame)
{
    m_lastFrame = frame;
    m_hasFrame  = true;
    m_markerSnapshot = frame.markerSnapshot;

    m_frameId   = frame.frameId;
    m_dropCount = frame.dropCount;

    recomputeScreenPoints();

    if (m_markerCard) {
        m_markerCard->updateMarkers(m_markerSnapshot.markers);
    }

    update();
}

// ── Events ──

void SpectrumPlot::resizeEvent(QResizeEvent* event)
{
    Q_UNUSED(event)
    m_gridDirty = true;
    recomputeScreenPoints();
    if (m_markerCard && !m_markerCard->isHidden()) {
        m_markerCard->resetToDefaultPosition();
    }
}

