void SpectrumPlot::drawMarkers(QPainter& painter)
{
    const QRect area = plotArea();
    painter.setClipRect(area);
    painter.setRenderHint(QPainter::Antialiasing, true);

    const double totalRange = m_dbPerDiv * kGridDivY;
    const double startFreq = m_centerFreq - m_span / 2.0;

    std::map<int, int> xBucketCount;

    for (const auto& m : m_markerSnapshot.markers) {
        if (!m.active) continue;

        double xNorm = (m.freqHz - startFreq) / m_span;
        double yNorm = (m_refLevel - m.amplitude) / totalRange;

        double x = area.left() + xNorm * area.width();
        double y = area.top() + yNorm * area.height();

        if (x < area.left() || x > area.right() || y < area.top() || y > area.bottom()) continue;

        int xBucket = static_cast<int>(x / 24);
        int overlapIndex = xBucketCount[xBucket]++;
        double yOffset = overlapIndex * 20.0;

        // Inverted triangle marker
        QPolygonF triangle;
        triangle << QPointF(x, y - yOffset)
                 << QPointF(x - 5, y - 8 - yOffset)
                 << QPointF(x + 5, y - 8 - yOffset);

        painter.setBrush(m.color);
        painter.setPen(QPen(Qt::black, 1));
        painter.drawPolygon(triangle);

        // Marker Tag Bubble
        QString tagText = QString("M%1: %2 %3dBm")
                              .arg(m.id)
                              .arg(formatFrequency(m.freqHz))
                              .arg(m.amplitude, 0, 'f', 1);
        if (m.isDelta) {
            tagText = QString("ΔM%1: %2 %3dB")
                          .arg(m.id)
                          .arg(formatFrequency(m.deltaFreqHz))
                          .arg(m.deltaAmplitude, 0, 'f', 1);
        }

        QFont tagFont("KaiTi", 8, QFont::Bold);
        painter.setFont(tagFont);
        QFontMetrics fm(tagFont);
        int tagW = fm.horizontalAdvance(tagText) + 8;
        int tagH = 15;

        int tagX = static_cast<int>(x) - tagW / 2;
        int tagY = static_cast<int>(y - 24 - yOffset);
        tagX = qBound(area.left() + 2, tagX, area.right() - tagW - 2);

        // Tag Background
        painter.fillRect(QRect(tagX, tagY, tagW, tagH), QColor(0x0e, 0x11, 0x1a, 230));
        painter.setPen(QPen(m.color, 1));
        painter.drawRect(QRect(tagX, tagY, tagW, tagH));

        // Tag Text
        painter.setPen(m.color);
        painter.drawText(QRect(tagX, tagY, tagW, tagH), Qt::AlignCenter, tagText);
    }

    painter.setClipping(false);
}

