void SpectrogramWidget::onNewFrame(const rtsa::ProcessedFrame& frame)
{
    if (frame.dBm.empty() || isHidden()) return;

    int plotW = width() - kMarginLeft - kMarginRight;
    int plotH = height() - kMarginTop - kMarginBottom;

    if (plotW <= 10 || plotH <= 10) return;

    // Ensure waterfall image dimensions strictly match current geometry
    if (m_waterfallImage.isNull() || m_waterfallImage.width() != plotW || m_waterfallImage.height() != plotH) {
        m_waterfallImage = QImage(plotW, plotH, QImage::Format_RGB32);
        m_waterfallImage.fill(QColor(0x0e, 0x11, 0x1a));
    }

    // 1. Fast Line Shift (move existing waterfall lines down by 1 row)
    if (plotH > 1) {
        int bytesPerLine = m_waterfallImage.bytesPerLine();
        uchar* bits = m_waterfallImage.bits();
        if (bits && bytesPerLine > 0) {
            std::memmove(bits + bytesPerLine, bits, static_cast<size_t>(bytesPerLine) * (plotH - 1));
        }
    }

    // 2. Render new line 0 (top row) with LUT lookup
    uint32_t* line0 = reinterpret_cast<uint32_t*>(m_waterfallImage.scanLine(0));
    if (!line0) return;

    if (!frame.waterfalldBm.empty()) {
        int srcSize = static_cast<int>(frame.waterfalldBm.size());
        for (int x = 0; x < plotW; ++x) {
            int srcIdx = (x * srcSize) / plotW;
            srcIdx = std::clamp(srcIdx, 0, srcSize - 1);
            line0[x] = mapPowerToRgb(frame.waterfalldBm[srcIdx]);
        }
    } else {
        int srcPairs = static_cast<int>(frame.dBm.size() / 2);
        if (srcPairs > 0) {
            for (int x = 0; x < plotW; ++x) {
                int pairIdx = (x * srcPairs) / plotW;
                pairIdx = std::clamp(pairIdx, 0, srcPairs - 1);
                float maxVal = frame.dBm[pairIdx * 2 + 1];
                line0[x] = mapPowerToRgb(maxVal);
            }
        }
    }

    update();
}

