QString FsmController::stateToString(FsmState state)
{
    switch (state) {
    case FsmState::Idle:        return "IDLE";
    case FsmState::Running:     return "RUNNING";
    case FsmState::SingleSweep: return "SINGLE";
    case FsmState::Calibrating: return "CALIBRATING";
    case FsmState::Fault:       return "FAULT";
    }
    return "UNKNOWN";
}

QString FsmController::stateString() const
{
    return stateToString(m_state);
}

bool FsmController::transitionTo(FsmState newState)
{
    if (m_state == newState) return true;

    // Check transition validity
    bool valid = false;

    switch (m_state) {
    case FsmState::Idle:
        valid = (newState == FsmState::Running ||
                 newState == FsmState::SingleSweep ||
                 newState == FsmState::Calibrating ||
                 newState == FsmState::Fault);
        break;
    case FsmState::Running:
        valid = (newState == FsmState::Idle ||
                 newState == FsmState::SingleSweep ||
                 newState == FsmState::Calibrating ||
                 newState == FsmState::Fault);
        break;
    case FsmState::SingleSweep:
        valid = (newState == FsmState::Idle ||
                 newState == FsmState::Running ||
                 newState == FsmState::Fault);
        break;
    case FsmState::Calibrating:
        valid = (newState == FsmState::Idle ||
                 newState == FsmState::Fault);
        break;
    case FsmState::Fault:
        valid = (newState == FsmState::Idle); // Only allowed to transition back to IDLE via resetFault
        break;
    }

    if (!valid) {
        Logger::warning(TAG, QString("Invalid transition: %1 -> %2")
                                 .arg(stateString())
                                 .arg(stateToString(newState)));
        return false;
    }

    FsmState oldState = m_state;
    m_state = newState;

    Logger::info(TAG, QString("State changed: %1 -> %2").arg(stateToString(oldState)).arg(stateToString(newState)));
    emit stateChanged(m_state, oldState);
    return true;
}

