#include "Logger.h"

#include <QDateTime>
#include <QDebug>
#include <QFile>
#include <QMutex>
#include <QMutexLocker>
#include <QTextStream>

namespace rtsa {

std::atomic<LogLevel> Logger::s_level{LogLevel::Debug};

static QFile* s_logFile = nullptr;
static QMutex s_mutex;

void Logger::init(const QString& logFilePath)
{
    QMutexLocker locker(&s_mutex);
    if (s_logFile) {
        if (s_logFile->isOpen()) {
            s_logFile->close();
        }
        delete s_logFile;
        s_logFile = nullptr;
    }

    if (!logFilePath.isEmpty()) {
        s_logFile = new QFile(logFilePath);
        if (!s_logFile->open(QIODevice::WriteOnly | QIODevice::Append | QIODevice::Text)) {
            delete s_logFile;
            s_logFile = nullptr;
        }
    }
}

void Logger::shutdown()
{
    QMutexLocker locker(&s_mutex);
    if (s_logFile) {
        if (s_logFile->isOpen()) {
            s_logFile->close();
        }
        delete s_logFile;
        s_logFile = nullptr;
    }
}

void Logger::setLevel(LogLevel level)
{
    s_level.store(level, std::memory_order_relaxed);
}

void Logger::debug(const QString& tag, const QString& message)
{
    log(LogLevel::Debug, tag, message);
}

void Logger::info(const QString& tag, const QString& message)
{
    log(LogLevel::Info, tag, message);
}

void Logger::warning(const QString& tag, const QString& message)
{
    log(LogLevel::Warning, tag, message);
}

void Logger::error(const QString& tag, const QString& message)
{
    log(LogLevel::Error, tag, message);
}

void Logger::log(LogLevel level, const QString& tag, const QString& message)
{
    if (level < s_level.load(std::memory_order_relaxed))
        return;

    static const char* levelNames[] = {"DEBUG", "INFO ", "WARN ", "ERROR"};

    QString timestamp = QDateTime::currentDateTime().toString("hh:mm:ss.zzz");
    QString line = QString("[%1] [%2] [%3] %4")
                       .arg(timestamp)
                       .arg(levelNames[static_cast<int>(level)])
                       .arg(tag, -12)
                       .arg(message);

    QMutexLocker locker(&s_mutex);

    // Console output
    switch (level) {
    case LogLevel::Debug:
        qDebug().noquote() << line;
        break;
    case LogLevel::Info:
        qInfo().noquote() << line;
        break;
    case LogLevel::Warning:
        qWarning().noquote() << line;
        break;
    case LogLevel::Error:
        qCritical().noquote() << line;
        break;
    }

    // File output
    if (s_logFile && s_logFile->isOpen()) {
        QTextStream stream(s_logFile);
        stream << line << "\n";
        stream.flush();
    }
}

} // namespace rtsa

