    });

    QObject::connect(bottomParamBar, &rtsa::BottomParamBar::spanChanged, [=](double hz) {
        applyParameters(spectrumPlot->centerFreq(), hz, spectrumPlot->refLevel());
    });

    QObject::connect(bottomParamBar, &rtsa::BottomParamBar::refLevelChanged, [=](double dBm) {
        applyParameters(spectrumPlot->centerFreq(), spectrumPlot->span(), dBm);
    });

    QObject::connect(bottomParamBar, &rtsa::BottomParamBar::scaleChanged, [=](double dbPerDiv) {
        spectrumPlot->setDbPerDiv(dbPerDiv);
    });

    // ── Connect ControlPanel SPAN preset buttons ──
    QObject::connect(controlPanel, &rtsa::ControlPanel::spanChanged, [=](double hz) {
        applyParameters(spectrumPlot->centerFreq(), hz, spectrumPlot->refLevel());
    });

    // ── Connect SpectrumPlot Drag & Zoom Shortcuts ──
    QObject::connect(spectrumPlot, &rtsa::SpectrumPlot::centerFreqUserChanged, [=](double hz) {
        applyParameters(hz, spectrumPlot->span(), spectrumPlot->refLevel());
    });

    QObject::connect(spectrumPlot, &rtsa::SpectrumPlot::spanUserChanged, [=](double hz) {
        applyParameters(spectrumPlot->centerFreq(), hz, spectrumPlot->refLevel());
    });

    QObject::connect(spectrumPlot, &rtsa::SpectrumPlot::refLevelUserChanged, [=](double dBm) {
        applyParameters(spectrumPlot->centerFreq(), spectrumPlot->span(), dBm);
    });

    // ── Connect Trace Multi-Channel Toggles ──
    QObject::connect(controlPanel, &rtsa::ControlPanel::traceToggled, [=](int traceIdx, bool enabled) {
        dataProcessor->setTraceEnabled(traceIdx, enabled);
    });

    QObject::connect(controlPanel, &rtsa::ControlPanel::resetAllTracesRequested, [=]() {
        dataProcessor->resetAllTraces();
    });

    // ── Connect Trace Color Picker ──
    QObject::connect(controlPanel, &rtsa::ControlPanel::traceColorChanged, [spectrumPlot](const QColor& color) {
        spectrumPlot->setTraceLiveColor(color);
        rtsa::Logger::info("Main", QString("波形显示颜色已更新为 %1 并保存").arg(color.name()));
    });

    // ── Connect Marker Actions (Independent) ──
    QObject::connect(controlPanel, &rtsa::ControlPanel::markerSelected, [=](int id) {
        if (!dataProcessor->markerEngine().marker(id).active) {
            dataProcessor->triggerPeakSearch(id);
        }
    });

    QObject::connect(controlPanel, &rtsa::ControlPanel::peakSearchRequested, [=](int id) {
        dataProcessor->triggerPeakSearch(id);
    });

    // ── Peak to Center (Peak -> Center) Helper ──
    auto doPeakToCenter = [=]() {
        dataProcessor->triggerPeakSearch(1);
        const auto& m1 = dataProcessor->markerEngine().marker(1);
        if (m1.active) {
            applyParameters(m1.freqHz, spectrumPlot->span(), spectrumPlot->refLevel());
            rtsa::Logger::info("Main", QString("峰值居中: 中心频率对齐至 %1 Hz").arg(m1.freqHz));
        }
    };

    QObject::connect(controlPanel, &rtsa::ControlPanel::peakToCenterRequested, doPeakToCenter);
    QObject::connect(spectrumPlot, &rtsa::SpectrumPlot::peakToCenterRequested, doPeakToCenter);

    QObject::connect(controlPanel, &rtsa::ControlPanel::peakRightRequested, [=](int id) {
        dataProcessor->triggerNextPeakRight(id);
    });

    QObject::connect(controlPanel, &rtsa::ControlPanel::peakLeftRequested, [=](int id) {
        dataProcessor->triggerNextPeakLeft(id);
    });

    QObject::connect(controlPanel, &rtsa::ControlPanel::minSearchRequested, [=](int id) {
        dataProcessor->triggerMinSearch(id);
    });

    QObject::connect(controlPanel, &rtsa::ControlPanel::continuousPeakToggled, [=](bool enabled, int markerId) {
        dataProcessor->setContinuousPeak(markerId, enabled);
    });

    QObject::connect(controlPanel, &rtsa::ControlPanel::globalDeltaToggled, [=](bool enable, int refId) {
        dataProcessor->markerEngine().setGlobalDelta(enable, refId);
    });

    QObject::connect(controlPanel, &rtsa::ControlPanel::clearAllMarkersRequested, [=]() {
        dataProcessor->markerEngine().setGlobalDelta(false, 1);
        for (int i = 1; i <= 6; ++i) {
            dataProcessor->markerEngine().setMarkerActive(i, false);
            dataProcessor->setContinuousPeak(i, false);
        }
        spectrumPlot->update();
    });

    // ── Full Span Shortcut Helper ──
    auto doFullSpan = [=]() {
        applyParameters(3005.0e6, 5990.0e6, spectrumPlot->refLevel());
        rtsa::Logger::info("Main", "激活全频跨度: 10 MHz ~ 6.0 GHz");
    };

    QObject::connect(controlPanel, &rtsa::ControlPanel::fullSpanRequested, doFullSpan);
    QObject::connect(spectrumPlot, &rtsa::SpectrumPlot::fullSpanRequested, doFullSpan);

    // ── Screenshot Helper ──
    auto doSaveScreenshot = [&window]() {
        QDir exportDir("exports");
        if (!exportDir.exists()) {
            QDir().mkdir("exports");
        }
        QString timestamp = QDateTime::currentDateTime().toString("yyyyMMdd_hhmmss");
        QString filename = QString("exports/screenshot_%1.png").arg(timestamp);

        QPixmap pixmap = window.grab();
        if (pixmap.save(filename)) {
            rtsa::Logger::info("Main", QString("屏幕截图已保存至 %1").arg(filename));
            QMessageBox::information(&window, "截图已保存",
                                     QString("当前屏幕截图已成功保存到:\n%1").arg(filename));
        } else {
            rtsa::Logger::error("Main", "保存截图失败");
            QMessageBox::warning(&window, "错误", "保存屏幕截图失败。");
        }
    };

    QObject::connect(controlPanel, &rtsa::ControlPanel::saveScreenshotRequested, doSaveScreenshot);
    QObject::connect(spectrumPlot, &rtsa::SpectrumPlot::screenshotRequested, doSaveScreenshot);

    // ── Context Menu Actions in SpectrumPlot ──
    QObject::connect(spectrumPlot, &rtsa::SpectrumPlot::peakSearchRequested, [=](int id) {
        dataProcessor->triggerPeakSearch(id);
    });

    QObject::connect(spectrumPlot, &rtsa::SpectrumPlot::resetTracesRequested, [=]() {
        dataProcessor->resetAllTraces();
    });

    // ── Spectrogram Toggle ──
    QObject::connect(controlPanel, &rtsa::ControlPanel::spectrogramToggled, [spectrogramWidget](bool show) {
        if (show) spectrogramWidget->show();
        else spectrogramWidget->hide();
    });

    // ── CSV Trace Export ──
    QObject::connect(controlPanel, &rtsa::ControlPanel::exportCsvRequested, [dataProcessor, spectrumPlot, &window]() {
        QDir exportDir("exports");
        if (!exportDir.exists()) {
            QDir().mkdir("exports");
        }
        QString timestamp = QDateTime::currentDateTime().toString("yyyyMMdd_hhmmss");
        QString filename = QString("exports/trace_%1.csv").arg(timestamp);

        QFile file(filename);
        if (file.open(QIODevice::WriteOnly | QIODevice::Text)) {
            QTextStream out(&file);
            out << "Frequency_Hz,Amplitude_dBm\n";

            double centerFreq = spectrumPlot->centerFreq();
            double span = spectrumPlot->span();
            double startFreq = centerFreq - span / 2.0;

            std::vector<float> processeddBm = dataProcessor->currentSpectrumTrace();
            int count = static_cast<int>(processeddBm.size());

            if (count > 0) {
                for (int i = 0; i < count; ++i) {
                    double freq = startFreq + (static_cast<double>(i) / count) * span;
                    out << QString::number(freq, 'f', 2) << ","
                        << QString::number(processeddBm[i], 'f', 2) << "\n";
                }
            }

            file.close();
            rtsa::Logger::info("Main", QString("迹线 CSV 数据已导出至 %1 (%2 点)").arg(filename).arg(count));
            QMessageBox::information(&window, "CSV 导出完成",
                                     QString("迹线数据已成功导出至:\n%1\n(共 %2 点)").arg(filename).arg(count));
        }
    });

    // ── FPS Update Timer ──
    auto* fpsTimer = new QTimer();
    QObject::connect(fpsTimer, &QTimer::timeout, [spectrumPlot, topBar]() {
        topBar->setFps(spectrumPlot->currentFps());
    });
    fpsTimer->start(500);

    // ── Create T1 DMA Thread ──
    auto* dmaThread = new rtsa::DmaRecvThread(hal, tripleBuffer);

    // Start threads & FSM
    fsmController->startRunning();
    dataProcessor->start();
    dmaThread->start();

    window.show();
    rtsa::Logger::info("Main", "RTSA-X 实时信号分析仪运行中");

    int result = app.exec();

    // Clean Shutdown
    dmaThread->stopThread();
    dmaThread->wait(2000);

    dataProcessor->stopThread();
    dataProcessor->wait(2000);

    fpsTimer->stop();

    delete fpsTimer;
    delete dmaThread;
    delete dataProcessor;
    delete tripleBuffer;
    delete paramTxn;
    delete fsmController;
    delete mock;

    return result;
}

